                layer = 9, strata = "AUTO", iconZoom = 100, iconScale = 100,
                _autoSeededSpecs = {},
            },
        }
    end

    return {
        gf_party = Scope(false),
        gf_raid = Scope(true),
        gf_mythicraid = Scope(true),
